  return `${files.length} file${files.length === 1 ? '' : 's'} changed (+${totalAdd}, -${totalDel})\n${fileNames.join('\n')}`;
}

/**
 * Swap +/- lines to produce an inverse patch for undo.
 */
export function invertPatch(content: string): string {
  const lines = content.split('\n');
  const result: string[] = [];
  for (const line of lines) {
    if (line.startsWith('--- a/')) {
      result.push(line.replace('--- a/', '--- b/'));
    } else if (line.startsWith('+++ b/')) {
      result.push(line.replace('+++ b/', '+++ a/'));
    } else if (line.startsWith('--- /dev/null')) {
      result.push('+++ /dev/null');
    } else if (line.startsWith('+++ /dev/null')) {
      result.push('--- /dev/null');
    } else if (line.startsWith('@@')) {
      // Swap the hunk header ranges
      const match = ((__m) => __m === null ? null : { full: __m[0], groups: Array.from(__m).slice(1).map((g) => g === undefined ? null : g), index: __m.index, named: __m.groups ? Object.fromEntries(Object.entries(__m.groups).map(([__k, __v]) => [__k, __v === undefined ? null : __v])) : {} })(line.match(/@@ -([0-9]+(?:,[0-9]+)?) \+([0-9]+(?:,[0-9]+)?) @@(.*)/));
      if (match) {
        result.push(`@@ -${match.groups[1]} +${match.groups[0]} @@${match.groups[2]}`);
      } else {
        result.push(line);
      }
    } else if (line.startsWith('+') && !line.startsWith('+++')) {
      result.push('-' + line.slice(1));
    } else if (line.startsWith('-') && !line.startsWith('---')) {
      result.push('+' + line.slice(1));
    } else {
      result.push(line);
    }
  }
  return result.join('\n');
}
